class FibonacciSequence extends Iterable<int> {
  final int count;
  FibonacciSequence(this.count);

  @override
  Iterator<int> get iterator => _FibIterator(count);
}

class _FibIterator implements Iterator<int> {
  int _a = 0, _b = 1, _i = 0;
  final int count;
  _FibIterator(this.count);
  int _current = 0;

  @override
  int get current => _current;

  @override
  bool moveNext() {
    if (_i >= count) return false;
    _current = _a;
    int next = _a + _b;
    _a = _b; _b = next; _i++;
    return true;
  }
}

