Future<Data> _fetchWithRetry({int attempt = 0}) async {
  try {
    return await api.fetch();
  } catch (e) {
    if (attempt >= 3) rethrow;
    await Future.delayed(Duration(seconds: 1 << attempt));
    return _fetchWithRetry(attempt: attempt + 1);
  }
}

