class HomeState extends Equatable {
  final bool isLoading;
  final List<Item> items;
  const HomeState({this.isLoading = false, this.items = const []});

  HomeState copyWith({bool? isLoading, List<Item>? items}) =>
      HomeState(
        isLoading: isLoading ?? this.isLoading,
        items: items ?? this.items,
      );
  @override
  List<Object> get props => [isLoading, items];
}

on<FetchNextPage>((event, emit) async {
  if (state.hasReachedMax) return;
  final newItems = await repo.fetchPage(state.page + 1);
  emit(state.copyWith(
    items: [...state.items, ...newItems],
    hasReachedMax: newItems.isEmpty,
    page: state.page + 1,
  ));
});

EventTransformer<T> debounce<T>(Duration duration) {
  return (events, mapper) => events
      .debounceTime(duration)
      .switchMap(mapper);
}

