// ❌ Without const: Reallocated every time build() runs
Widget badWidget() => Text('Hello World');

// ✅ With const: Allocated once at compile-time in canonical memory,
// shared across all references with zero extra heap allocation
Widget goodWidget() => const Text('Hello World');

// ❌ Bad: Entire tree rebuilds when counter changes
// setState(() => counter++);

// ✅ Good: Only localized text rebuilds using ValueListenableBuilder
final ValueNotifier<int> counter = ValueNotifier<int>(0);

ValueListenableBuilder<int>(
  valueListenable: counter,
  builder: (context, value, _) => Text('$value'),
);

